function stepsReset(e) {
    let stepStation = e.getWidgetRef('stepStation', false);
    let stepStationSup = e.getWidgetRef('stepStationSup', false);

    for(var i=0;i<stepStation.widget.options.steps.length;i++)
    {
      stepStation.widget.options.steps[i].status = 'wait';
    }

    for(var j=0;j<stepStationSup.widget.options.steps.length;j++)
    {
      stepStationSup.widget.options.steps[j].status = 'wait';
    }
}

